-- 419: Original BrillaPrep WASSCE Integrated Science beta questions, part 7 of 8 (sprint 1 batch 001).
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_419_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_419_guard;
INSERT INTO _migration_419_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_hlt_b001_005' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_hlt' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Clearing stagnant water from around homes helps to control malaria because it:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Kills the Plasmodium parasite directly","B. Stops mosquitoes from feeding at night","C. Destroys the breeding sites where mosquito larvae develop","D. Makes the air too dry for adult mosquitoes to fly"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Mosquitoes lay eggs in stagnant water where the larvae develop; draining or covering such water breaks the life cycle, so fewer adult mosquitoes emerge to transmit the parasite.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_hlt_b001_005' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_419_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_hlt_b001_006' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_hlt' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'The most immediate danger to a person suffering from cholera is:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. High fever causing brain damage","B. The bacteria invading the lungs","C. Permanent damage to the eyesight","D. Severe dehydration from the rapid loss of water and salts through diarrhoea"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Cholera causes profuse watery diarrhoea and vomiting; rapid loss of water and salts leads to fatal dehydration within hours, so oral rehydration solution is the key first treatment.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_hlt_b001_006' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_419_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_hlt_b001_007' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_hlt' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Tuberculosis is mainly spread when:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Droplets coughed or sneezed by an infected person are inhaled","B. Contaminated food is eaten","C. An infected mosquito bites a healthy person","D. Open wounds come into contact with soil"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Tuberculosis is an airborne disease: a patient releases bacteria-laden droplets when coughing, sneezing or speaking, and people nearby inhale them into their lungs.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_hlt_b001_007' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_419_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_hlt_b001_008' AND NOT (q.topic_id IS 'topic_wassce_p2_sci_hlt' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Community pipe-borne water is treated with chlorine mainly to:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Give the water a salty taste","B. Kill disease-causing micro-organisms in the water","C. Remove all dissolved minerals from the water","D. Increase the oxygen content of the water"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Chlorination disinfects water by killing bacteria, viruses and other pathogens, preventing water-borne diseases such as cholera and typhoid.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_hlt_b001_008' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_419_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_reproduction_b001_001' AND NOT (q.topic_id IS 'topic_wassce_intsci_reproduction' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which of the following is an example of asexual reproduction?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Fertilisation in humans","B. Pollination in maize","C. Cross-breeding of cattle","D. Budding in yeast"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Budding involves a single parent and no fusion of gametes, so it is asexual reproduction. Fertilisation, pollination (leading to fertilisation) and cross-breeding all involve gametes from two parents.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_reproduction_b001_001' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_419_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_wisc_reproduction_b001_002' AND NOT (q.topic_id IS 'topic_wassce_intsci_reproduction' AND q.subject_id IS 'subj_wassce_int_science' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'In flowering plants, pollination is best described as the:' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Fusion of the male and female gametes","B. Transfer of pollen grains from the anther to the stigma","C. Development of the ovule into a seed","D. Release of seeds from a ripe fruit"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Pollination is the transfer of pollen (carrying the male gametes) from anther to stigma by wind, insects or other agents. The fusion of gametes that follows is fertilisation, a separate event.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '1' AND q.time_limit IS '45' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_wisc_reproduction_b001_002' AND NOT (r.batch_id IS 'wassce-int-science-sprint1-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep curriculum-aligned WASSCE Integrated Science practice; not official WAEC examination material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
